PENAL_QUESTIONS.push({"id":"fcc-penal-258791","sourceQuestionId":"258791","t":"pen-m12","moduleId":"pen-m12","q":"João Ricardo, Técnico de Segurança Institucional, recebeu a incumbência de entregar uma intimação para um Promotor de Justiça. Ao saber que ele se encontrava no sítio da família, para lá se dirigiu e foi recebido por um segurança particular que, de arma em punho, ignorou as credenciais de João Ricardo, proferindo contra este palavras de desafio ofensivas, e impediu que ele entregasse a intimação. Nesta situação, os atos cometidos caracterizaram crime de","o":["desobediência por parte de João Ricardo, pois não acatou ordem emanada de autoridade competente e o segurança cometeu o crime de desacato, pois ofendeu João Ricardo no desempenho da sua função de funcionário público.","desobediência por parte de João Ricardo, pois deixou de entregar a intimação de que fora incumbido. Já no caso do segurança, não houve crime na sua conduta, na medida em que cumpriu expressamente as orientações do Promotor de Justiça.","resistência e desacato por parte do segurança, pois impediu, mediante ameaça, que João Ricardo intimasse o Promotor de Justiça, bem como João Ricardo foi desrespeitado no exercício da sua função, assumindo a condição de sujeito passivo.","desobediência por parte do segurança, por descumprir a ordem de João Ricardo de permitir a sua entrada no sítio, o que resultou na impossibilidade deste de entregar a intimação, sendo, então, sujeito passivo.","desacato, praticado pelo segurança, pois desrespeitou João Ricardo no exercício da sua função, mas não há a caracterização do crime de resistência, porque o sujeito ativo desse crime tem que ser funcionário público."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Tec (CNMP)/CNMP/Apoio Técnico Administrativo/Segurança Institucional/2015 • TEC 258791","source":"FCC - Tec (CNMP)/CNMP/Apoio Técnico Administrativo/Segurança Institucional/2015","subject":"Direito Penal - Questões Mescladas sobre Crimes Praticados por Particular contra a Administração em Geral (arts. 328 a 337-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/258791","year":2015,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-300291","sourceQuestionId":"300291","t":"pen-m12","moduleId":"pen-m12","q":"NÃO constitui crime praticado por particular contra a Administração em geral","o":["o tráfico de influência.","a desobediência.","a resistência.","a advocacia administrativa.","o desacato."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JE TJAL/TJ AL/2015 • TEC 300291","source":"FCC - JE TJAL/TJ AL/2015","subject":"Direito Penal - Questões Mescladas sobre Crimes Praticados por Particular contra a Administração em Geral (arts. 328 a 337-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300291","year":2015,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-150510","sourceQuestionId":"150510","t":"pen-m12","moduleId":"pen-m12","q":"O crime de","o":["contrabando é punível tanto na forma dolosa, quanto na culposa.","falso testemunho não pode ser cometido pelo réu, mas pode ser praticado pela vítima do delito.","auto-acusação falsa consuma-se quando o agente assume a autoria do crime inexistente ou praticado por outrem perante populares e nega perante a autoridade policial.","resistência só se consuma quando, em razão da conduta do agente, o ato legal não é executado pelo funcionário público competente para executá-lo.","desacato pode caracterizar-se mesmo quando o funcionário público não esteja no exercício da função, desde que a ofensa esteja com ela relacionada."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TJ PE)/TJ PE/Judiciária e Administrativa/2012 • TEC 150510","source":"FCC - AJ (TJ PE)/TJ PE/Judiciária e Administrativa/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes Praticados por Particular contra a Administração em Geral (arts. 328 a 337-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/150510","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-181771","sourceQuestionId":"181771","t":"pen-m12","moduleId":"pen-m12","q":"No que concerne aos crimes praticados por particular contra a Administração em geral e contra a Administração da Justiça, é correto afirmar que quem","o":["exporta mercadoria proibida não comete crime de contrabando.","comete crime de resistência na modalidade culposa está sujeito apenas a sanção pecuniária.","ilude o pagamento de direito ou imposto devido pela entrada, pela saída ou pelo consumo de mercadoria comete crime de descaminho.","dá causa a investigação policial contra alguém, imputando-lhe crime de que o sabe inocente comete o delito de comunicação falsa de crime.","acusar-se, perante a autoridade, de crime praticado por outrem não comete infração penal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Proc (João Pessoa)/Pref João Pessoa/2012 • TEC 181771","source":"FCC - Proc (João Pessoa)/Pref João Pessoa/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes Praticados por Particular contra a Administração em Geral (arts. 328 a 337-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/181771","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-225407","sourceQuestionId":"225407","t":"pen-m12","moduleId":"pen-m12","q":"No que concerne aos crimes praticados contra a Administração em geral, é correto afirmar:","o":["O crime de resistência só se consuma se, em razão da violência ou grave ameaça, o ato legal não vier a ser executado.","A reintrodução no país de produtos de fabricação nacional destinados exclusivamente à exportação e de venda proibida no Brasil, constitui crime de contrabando.","O crime de desacato admite a forma culposa quando o agente estiver no exercício de suas funções.","O crime de corrupção passiva admite a forma culposa quando cometido através de interposta pessoa.","O funcionário público, estando fora de suas funções, não pode cometer crime de desobediência."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE PR/TRE PR/Judiciária/2012 • TEC 225407","source":"FCC - AJ TRE PR/TRE PR/Judiciária/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes Praticados por Particular contra a Administração em Geral (arts. 328 a 337-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/225407","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-65242","sourceQuestionId":"65242","t":"pen-m12","moduleId":"pen-m12","q":"João, funcionário público no exercício de suas funções, em cumprimento de mandado de citação, abordou José, o citando, ordenando-lhe que ajoelhasse no chão para ouvir a leitura do teor do mandado. José recusou-se a ajoelhar-se, dizendo que ouviria de pé. Nesse caso, José","o":["cometeu crime de desacato.","cometeu crime de desobediência.","não cometeu nenhum delito.","cometeu crime de resistência simples.","cometeu crime de resistência qualificada."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TRF 1ª Região)/TRF 1/Judiciária/Oficial de Justiça Avaliador Federal/2011 • TEC 65242","source":"FCC - AJ (TRF 1ª Região)/TRF 1/Judiciária/Oficial de Justiça Avaliador Federal/2011","subject":"Direito Penal - Questões Mescladas sobre Crimes Praticados por Particular contra a Administração em Geral (arts. 328 a 337-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/65242","year":2011,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3826873","sourceQuestionId":"3826873","t":"pen-m16","moduleId":"pen-m16","q":"Considere as seguintes situações: I. Vicente tentou afastar licitante por meio de violência; II. Hermínio desistiu de licitar em razão de vantagem oferecida; III. Cacilda patrocinou diretamente interesse privado perante a Administração Pública, dando causa à celebração de contrato cuja invalidação não veio a ser decretada pelo Poder Judiciário. Por força da Lei nº 14.133/2021, com base apenas nas informações fornecidas, Vicente","o":["cometeu crime de afastamento de licitante, incorrendo em pena de detenção de 6 meses a 3 anos e multa, além da pena correspondente à violência; Hermínio incorre na mesma pena de Vicente; e Cacilda não cometeu crime de patrocínio de contratação indevida.","cometeu crime de afastamento de licitante, incorrendo em pena de detenção de 6 meses a 3 anos e multa, além da pena correspondente à violência; Hermínio cometeu crime de contratação inidônea, incorrendo na pena de reclusão de 3 a 5 anos e multa; e Cacilda incorre na pena de reclusão, de 6 meses a 3 anos e multa, por ter cometido o crime de patrocínio de contratação indevida.","cometeu crime de afastamento de licitante, incorrendo em pena de reclusão de 3 a 5 anos e multa, além da pena correspondente à violência; Hermínio incorre na mesma pena de Vicente; e Cacilda não cometeu crime de patrocínio de contratação indevida.","não cometeu crime de afastamento de licitante; Hermínio cometeu crime de fraude em licitação ou contrato, incorrendo em pena de reclusão de 4 a 8 anos e multa; e Cacilda incorre na pena de reclusão, de 6 meses a 3 anos e multa, por ter cometido o crime de patrocínio de contratação indevida.","não cometeu crime de afastamento de licitante; Hermínio cometeu crime de fraude em licitação ou contrato, incorrendo em pena de reclusão de 4 a 8 anos e multa; e incorre na mesma pena de Hermínio."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 16: Crimes em licitações e contratos.","r":"FCC - Tec (MPE SE)/MPE SE/Administrativa/2026 • TEC 3826873","source":"FCC - Tec (MPE SE)/MPE SE/Administrativa/2026","subject":"Direito Penal - Dos Crimes em Licitações e Contratos Administrativos (arts. 337-E a 337-P do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3826873","year":2026,"caderno":6,"classificationReason":"Crimes licitatórios expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2872495","sourceQuestionId":"2872495","t":"pen-m16","moduleId":"pen-m16","q":"De acordo com o que estabelece a Lei de Licitações e Contratos Administrativos (Lei nº 14.133/2021), a conduta de impedir a realização de qualquer ato de processo licitatório é prevista como crime de","o":["Contratação inidônea.","Patrocínio de contratação indevida.","Fraude em licitação ou contrato.","Frustração do caráter competitivo de licitação.","Perturbação de processo licitatório."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 16: Crimes em licitações e contratos.","r":"FCC - Ag Ap (MPE AM)/MPE AM/Administrativo/2024 • TEC 2872495","source":"FCC - Ag Ap (MPE AM)/MPE AM/Administrativo/2024","subject":"Direito Penal - Dos Crimes em Licitações e Contratos Administrativos (arts. 337-E a 337-P do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2872495","year":2024,"caderno":6,"classificationReason":"Crimes licitatórios expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2975471","sourceQuestionId":"2975471","t":"pen-m16","moduleId":"pen-m16","q":"As empresas \"X\" e \"Z\" pretendem participar de procedimentos licitatórios promovidos por uma Prefeitura de determinada cidade de grande porte do Estado de São Paulo. Os objetos dos contratos são a construção de uma escola e de um hospital. Após a publicação dos respectivos editais, as empresas \"X\" e \"Z\", por meio de seus representantes legais, com o escopo de vencer os procedimentos licitatórios abertos, se reúnem antes de apresentarem as propostas ao Poder Público na sede de uma das empresas e combinam os valores que seriam propostos em ambos os certames. A empresa \"X\" apresentaria proposta menor para um dos contratos, enquanto a empresa \"Z\" apresentaria proposta menor para o outro, tudo para conseguirem um rodízio na contratação com o Poder Público. Neste caso, na esteira da Lei nº 14.133/2021, os representantes legais das empresas \"X\" e \"Z\" praticaram, em tese, o crime de","o":["afastamento de licitante.","fraude em licitação ou contrato.","modificação ou pagamento irregular em contrato administrativo.","frustração do caráter competitivo de licitação.","violação de sigilo em licitação."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 16: Crimes em licitações e contratos.","r":"FCC - Adv (CETESB)/CETESB/2024 • TEC 2975471","source":"FCC - Adv (CETESB)/CETESB/2024","subject":"Direito Penal - Dos Crimes em Licitações e Contratos Administrativos (arts. 337-E a 337-P do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2975471","year":2024,"caderno":6,"classificationReason":"Crimes licitatórios expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3021825","sourceQuestionId":"3021825","t":"pen-m16","moduleId":"pen-m16","q":"A empresa \"X\", declarada inidônea, é admitida pelos funcionários públicos José, Mônica e Rubens, à licitação promovida pelo órgão federal em que lotados. Nesse caso, nos termos preconizados pelo Código Penal, José, Mônica e Rubens cometeram, em tese, o crime de","o":["Modificação ou pagamento irregular em contrato administrativo - artigo 337-H, do Código Penal.","Frustração do caráter competitivo de licitação - artigo 337-F, do Código Penal.","Contratação inidônea - artigo 337-M, do Código Penal.","Fraude em licitação ou contrato - artigo 337-L, do Código Penal.","Afastamento de licitante - art. 337-K, do Código Penal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 16: Crimes em licitações e contratos.","r":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024 • TEC 3021825","source":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Penal - Dos Crimes em Licitações e Contratos Administrativos (arts. 337-E a 337-P do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3021825","year":2024,"caderno":6,"classificationReason":"Crimes licitatórios expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3177515","sourceQuestionId":"3177515","t":"pen-m16","moduleId":"pen-m16","q":"Um servidor que tenha se comportado de modo a frustrar o caráter competitivo de um processo licitatório, com o intuito de beneficiar uma empresa que lhe tenha prometido vantagem pecuniária,","o":["deve ser responsabilizado por infração criminal, esta que prefere às demais infrações, dada a maior gravidade.","pode ser responsabilizado por ato de improbidade, diante da conduta culposa e do nexo de causalidade comprovado.","comete crime tipificado na lei de licitações e contratos.","deve ser responsabilizado por infração disciplinar e, no âmbito de improbidade e criminal, se liver havido prejuizo ao erário.","comete ato de improbidade que causa prejuízo ao erário."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 16: Crimes em licitações e contratos.","r":"FCC - TJ TRT7/TRT 7/Administrativa/Agente da Policia Judicial/2024 • TEC 3177515","source":"FCC - TJ TRT7/TRT 7/Administrativa/Agente da Policia Judicial/2024","subject":"Direito Penal - Dos Crimes em Licitações e Contratos Administrativos (arts. 337-E a 337-P do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3177515","year":2024,"caderno":6,"classificationReason":"Crimes licitatórios expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3231599","sourceQuestionId":"3231599","t":"pen-m16","moduleId":"pen-m16","q":"Alípio, funcionário público de determinado município brasileiro, agindo de forma dolosa, deu causa, sem autorização em lei, nos respectivos instrumentos contratuais, a prorrogação contratual em favor do contratado, durante a execução dos contratos celebrados com a Administração Pública. Neste caso, de acordo com a tipificação dos crimes em licitações e contratos administrativos prevista no Código Penal, Alípio cometeu, em tese, o crime de","o":["impedimento indevido, previsto no artigo 337-N, do Código Penal.","contratação inidônea, previsto no artigo 337-M, do Código Penal.","modificação ou pagamento Irregular em contrato administrativo, previsto no artigo 337-H, do Código Penal.","afastamento de licitante, previsto artigo 337-K, do Código Penal.","fraude em licitação ou contrato, previsto no artigo 337-L, do Código Penal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 16: Crimes em licitações e contratos.","r":"FCC - Ana Prev (PIAUÍPREV)/PIAUÍPREV/2024 • TEC 3231599","source":"FCC - Ana Prev (PIAUÍPREV)/PIAUÍPREV/2024","subject":"Direito Penal - Dos Crimes em Licitações e Contratos Administrativos (arts. 337-E a 337-P do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3231599","year":2024,"caderno":6,"classificationReason":"Crimes licitatórios expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-460661","sourceQuestionId":"460661","t":"pen-m12","moduleId":"pen-m12","q":"Ricardo reside na cidade de São Paulo e acaba testemunhando, da janela de sua residência, o furto de um veículo que estava estacionado na via pública, defronte ao seu imóvel, praticado por dois agentes. Para se vingar do seu desafeto e vizinho Rodolfo e sabendo de sua inocência, Ricardo apresenta uma denúncia anônima à Polícia noticiando que Rodolfo foi um dos autores do referido crime de furto. A autoridade policial determina a instauração de inquérito policial para apuração da autoria delitiva em relação a Rodolfo. Nesse caso hipotético, Ricardo cometeu crime de","o":["denunciação caluniosa, com pena prevista de reclusão de dois a oito anos e multa, aumentada de sexta parte, pois serviuse de anonimato.","comunicação falsa de crime, com pena prevista de detenção de um a seis meses ou multa, aumentada de sexta parte, pois serviu-se de anonimato.","denunciação caluniosa, com pena prevista de reclusão de dois a oito anos e multa, sem qualquer majoração.","comunicação falsa de crime, com pena prevista de detenção de um a seis meses ou multa sem qualquer majoração.","falso testemunho."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE SP/TRE SP/Administrativa/\"Sem Especialidade\"/2017 • TEC 460661","source":"FCC - AJ TRE SP/TRE SP/Administrativa/\"Sem Especialidade\"/2017","subject":"Direito Penal - Denunciação Caluniosa (art. 339 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/460661","year":2017,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-357284","sourceQuestionId":"357284","t":"pen-m12","moduleId":"pen-m12","q":"A respeito dos Crimes contra a Administração pública,","o":["o crime de resistência não se configura se a oposição do agente, mediante violência ou grave ameaça, não obstar a execução do ato legal do funcionário público.","o não atendimento a ordem ilegal de funcionário público caracteriza o crime de desobediência.","no crime de denunciação caluniosa, o uso do anonimato agrava a pena a ser aplicada.","quem esconde em sua residência autor de crime de roubo para evitar a sua prisão em flagrante comete o crime de favorecimento real.","o empréstimo de sacola para permitir o transporte e ocultação de objetos furtados por outrem configura o crime de favorecimento pessoal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TJ TRF3/TRF 3/Apoio Especializado/Informática/2016 • TEC 357284","source":"FCC - TJ TRF3/TRF 3/Apoio Especializado/Informática/2016","subject":"Direito Penal - Denunciação Caluniosa (art. 339 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/357284","year":2016,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-315492","sourceQuestionId":"315492","t":"pen-m12","moduleId":"pen-m12","q":"Xisto, Vereador de um determinado município do Estado de Sergipe, com o escopo de vingar-se do seu desafeto Tácito, também Vereador do mesmo município, faz uma denúncia escrita de crime eleitoral perante a Autoridade Policial contra Tácito, sabendo da inocência deste, apresentando-se como Moisés para não ser identificado. O Inquérito Policial é instaurado pela Autoridade Policial. Neste caso Xisto cometeu crime de","o":["denunciação caluniosa com pena de 2 a 8 anos, aumentada de um terço.","comunicação falsa de crime, com pena de 1 a 6 meses de detenção e multa, aumentada de um terço.","denunciação caluniosa com pena de 2 a 8 anos e multa, aumentada da sexta parte.","comunicação falsa de crime, com pena de 1 a 6 meses de detenção e multa, sem qualquer majoração.","denunciação caluniosa, com pena de 2 a 8 anos, sem qualquer majoração."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE SE/TRE SE/Judiciária/2015 • TEC 315492","source":"FCC - AJ TRE SE/TRE SE/Judiciária/2015","subject":"Direito Penal - Denunciação Caluniosa (art. 339 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/315492","year":2015,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-684087","sourceQuestionId":"684087","t":"pen-m12","moduleId":"pen-m12","q":"Dar causa à instauração de ação de improbidade administrativa contra alguém, imputando-lhe crime de que sabe inocente:","o":["configura o delito de comunicação falsa de crime.","configura o delito de denunciação caluniosa.","configura o delito de fraude processual.","configura o delito de auto-acusação falsa.","não tem relevância penal, porque a ação de improbidade administrativa é ação cível."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Ana Min (MPE PE)/MPE PE/Arquitetura/2012 • TEC 684087","source":"FCC - Ana Min (MPE PE)/MPE PE/Arquitetura/2012","subject":"Direito Penal - Denunciação Caluniosa (art. 339 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/684087","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-225459","sourceQuestionId":"225459","t":"pen-m12","moduleId":"pen-m12","q":"O crime de comunicação falsa de crime ou contravenção","o":["não admite a forma culposa.","não pode ser praticado por funcionário público no exercício de suas funções.","exige a formalização da falsa comunicação através de documento escrito.","só ocorre se a comunicação tiver sido dirigida a autoridade policial.","só se consuma quando tiver sido instaurado inquérito policial a respeito."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE PR/TRE PR/Administrativa/\"Sem Especialidade\"/2012 • TEC 225459","source":"FCC - AJ TRE PR/TRE PR/Administrativa/\"Sem Especialidade\"/2012","subject":"Direito Penal - Comunicação Falsa de Crime ou de Contravenção (art. 340 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/225459","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-526971","sourceQuestionId":"526971","t":"pen-m12","moduleId":"pen-m12","q":"Luiz, condenado há vários anos de prisão pela prática de diversos crimes assume, perante a autoridade, a autoria de crime que não cometeu, com o intuito de livrar outra pessoa da condenação. Assim agindo, Luiz","o":["praticou o crime de comunicação falsa de crime.","não praticou qualquer tipo penal.","praticou o crime de fraude processual.","praticou o crime de denunciação caluniosa.","praticou o crime de auto-acusação falsa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE PR/TRE PR/Judiciária/2017 • TEC 526971","source":"FCC - AJ TRE PR/TRE PR/Judiciária/2017","subject":"Direito Penal - Auto-Acusação Falsa (art. 341 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/526971","year":2017,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-592145","sourceQuestionId":"592145","t":"pen-m12","moduleId":"pen-m12","q":"A retratação do agente torna o fato impunível no crime de","o":["injúria, se realizada antes da sentença de maneira cabal.","falsidade ideológica, se realizada até o recebimento da denúncia.","sonegação de contribuição previdenciária, realizada a qualquer tempo.","ameaça, se realizada até o oferecimento da denúncia.","falso testemunho ou falsa perícia, se realizada antes da sentença no processo em que ocorreu o ilícito."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - DP AM/DPE AM/2018 • TEC 592145","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592145","year":2018,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-638438","sourceQuestionId":"638438","t":"pen-m12","moduleId":"pen-m12","q":"Sobre o crime de falso testemunho ou falsa perícia, o Código Penal, em seu artigo 342, prevê que","o":["é fato atípico fazer afirmação falsa em juízo arbitral.","é fato atípico fazer afirmação falsa em inquérito penal.","as penas são aumentadas de um sexto a um terço, se o crime é praticado mediante suborno ou se cometido com o fim de obter prova destinada a produzir efeito em processo penal, ou em processo civil em que for parte entidade da Administração pública direta ou indireta.","o fato deixa de ser típico se, antes da sentença no processo em que ocorreu o ilícito, o agente se retrata ou declara a verdade.","é fato atípico fazer afirmação falsa em processo administrativo."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Ana Leg (ALESE)/ALESE/Técnico Jurídica/Apoio Jurídico/2018 • TEC 638438","source":"FCC - Ana Leg (ALESE)/ALESE/Técnico Jurídica/Apoio Jurídico/2018","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/638438","year":2018,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-460489","sourceQuestionId":"460489","t":"pen-m12","moduleId":"pen-m12","q":"O Delegado de Polícia de um determinado município paulista recebe a notícia de um crime de roubo que vitimou Alfredo, que teve seu veículo subtraído por um agente mediante grave ameaça, com emprego de arma de fogo. Durante o trâmite do Inquérito Policial apura-se que Joaquim foi o autor do crime, o qual tem a sua prisão preventiva decretada. Ainda na fase policial Fabíola, a pedido de Joaquim, comparece na Delegacia de Polícia para prestar depoimento e alega que Joaquim, seu amigo, estava em sua companhia no momento do crime. Encerrado o Inquérito Policial o Ministério Público denuncia Joaquim pelo crime de roubo, denúncia esta recebida pelo Magistrado competente. Fabíola não é encontrada para prestar depoimento em juízo sob o crivo do contraditório, mesmo arrolada pela Defesa de Joaquim. Ao final do processo Joaquim é condenado pelo crime de roubo em primeira instância e, posteriormente, é instaurada ação penal contra Fabíola por crime de falso testemunho. Durante o trâmite do recurso interposto por Joaquim contra a sentença que o condenou por crime de roubo, e da ação penal instaurada por falso testemunho contra Fabíola, esta resolve se retratar, afirmando que Joaquim não estava com ela no dia do crime. No caso hipotético apresentado, na esteira do Código Penal, Fabíola","o":["não cometeu crime de falso testemunho, pois prestou depoimento falso apenas durante o trâmite do Inquérito Policial.","será regularmente processada pelo crime de falso testemunho e estará sujeita à pena cominada ao delito, sem qualquer causa de redução de pena.","não poderá ser punida por crime de falso testemunho, pois se retratou antes da sentença proferida nos autos da ação penal instaurada por falto testemunho.","será regularmente processada pelo crime de falso testemunho e estará sujeita à pena cominada ao delito no Código Penal, reduzida de 1/3.","será regularmente processada pelo crime de falso testemunho e estará sujeita à pena cominada ao delito no Código Penal, reduzida de 1/6."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE SP/TRE SP/Judiciária/2017 • TEC 460489","source":"FCC - AJ TRE SP/TRE SP/Judiciária/2017","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/460489","year":2017,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-541360","sourceQuestionId":"541360","t":"pen-m12","moduleId":"pen-m12","q":"Guilherme, médico legista, responsável por elaborar o laudo de exumação de Danilo, em investigação de morte suspeita, é procurado por Rodrigo que, temendo ser acusado de homicídio contra a vítima, oferece suborno para que Guilherme afirmasse falsamente que a morte se deu por causas naturais. O médico aceita a promessa de pagamento e conclui o laudo, a despeito de extensas evidências de agressões físicas, no sentido de que Danilo morreu em decorrência de problemas cardíacos. Passadas algumas semanas, Guilherme, arrependido de sua conduta, procura o juiz responsável pelo processo e se retrata, declarando que a morte da vítima ocorreu em virtude das lesões corporais sofridas, antes de ser proferida a sentença. Diante dessa situação hipotética,","o":["Guilherme responderá pelo crime de falsa perícia, ainda que tenha se retratado, com a pena aumentada de um sexto a um terço, por ter praticado o delito com o fim de obter prova destinada a produzir efeito em processo penal.","a conduta de Guilherme não será punível por ter se retratado antes da sentença no processo em que ocorreu a falsa perícia.","Guilherme terá sua pena diminuída de um a dois terços por ter se retratado antes da sentença.","Guilherme somente teria sua pena diminuída se tivesse se retratado antes do início da ação penal.","Guilherme, embora tenha se retratado, responderá pelo crime de falsa perícia, sem qualquer diminuição de pena."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - PML (PCA AP)/PCA AP/Psiquiatria/2017 • TEC 541360","source":"FCC - PML (PCA AP)/PCA AP/Psiquiatria/2017","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/541360","year":2017,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-283578","sourceQuestionId":"283578","t":"pen-m12","moduleId":"pen-m12","q":"Petrus fez afirmação falsa em processo criminal. Todavia, a sentença não levou em conta o seu depoimento por estar em descordo com o conjunto probatório colhido. Nesse caso, Petrus","o":["responderá pelo crime de falso testemunho na forma privilegiada, com redução de pena de 1 a 2 terços.","não responderá pelo crime de falso testemunho por não ter o depoimento influído na decisão da causa.","não responderá por crime de falso testemunho por se tratar de processo criminal.","responderá pelo crime de falso testemunho em seu tipo fundamental.","só responderá pelo crime de falso testemunho se a sentença for absolutória."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - ACI (CGM São Luís)/Pref São Luís/Engenharia Elétrica/2015 • TEC 283578","source":"FCC - ACI (CGM São Luís)/Pref São Luís/Engenharia Elétrica/2015","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/283578","year":2015,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-320949","sourceQuestionId":"320949","t":"pen-m12","moduleId":"pen-m12","q":"Rodrigo está sendo processado por crime de roubo cometido na cidade de Jardim Azul. Na defesa preliminar, Petrônio é arrolado como testemunha de defesa. Durante audiência de instrução e julgamento Petrônio faz afirmação falsa na condição de testemunha ao relatar ao magistrado que o réu Rodrigo estava em sua casa no momento do crime. O delito de falso testemunho deixará de ser punido se Petrônio se retratar ou declarar a verdade até","o":["o início do interrogatório do réu no processo pelo crime de roubo em que Petrônio depôs como testemunha.","a data da prolação da sentença no processo pelo crime de roubo em que Petrônio depôs como testemunha.","o julgamento do recurso de apelação no processo pelo crime de roubo em que Petrônio depôs como testemunha.","a data do recebimento da denúncia na ação penal pelo crime de falso testemunho.","a data da prolação da sentença no processo pelo crime de falso testemunho."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TRE PB)/TRE PB/Administrativa/\"Sem Especialidade\"/2015 • TEC 320949","source":"FCC - AJ (TRE PB)/TRE PB/Administrativa/\"Sem Especialidade\"/2015","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/320949","year":2015,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-132704","sourceQuestionId":"132704","t":"pen-m12","moduleId":"pen-m12","q":"Em audiência judicial, o intérprete que, dolosamente, traduz declaração de testemunha de modo contrário ao teor do depoimento, todavia que se retrata por escrito, depois de proferida a sentença, mas antes do trânsito em julgado,","o":["não comete o crime de falso testemunho ou perícia por ocorrência de causa excludente da ilicitude.","comete o crime de falso testemunho ou falsa perícia no modo tentado.","não comete o crime de falso testemunho ou perícia, pois intérprete não é testemunha ou perito.","comete o crime de falso testemunho ou perícia, mas está isento de pena pela retratação.","comete o crime de falso testemunho ou falsa perícia no modo consumado."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRF5/TRF 5/Judiciária/Oficial de Justiça Avaliador Federal/2013 • TEC 132704","source":"FCC - AJ TRF5/TRF 5/Judiciária/Oficial de Justiça Avaliador Federal/2013","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/132704","year":2013,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-184075","sourceQuestionId":"184075","t":"pen-m12","moduleId":"pen-m12","q":"No que concerne ao crime de falso testemunho, correto afirmar que","o":["o juiz, havendo indícios de que alguma testemunha fez afirmação falsa, só poderá remeter cópia do depoimento à autoridade policial para instauração de inquérito se assim o requerer a parte contrária ou o Ministério Público.","não interfere na pena o fato de haver sido praticado mediante suborno.","compete à Justiça Estadual processá-lo e julgá-lo se cometido no processo trabalhista.","não se configura se o agente apenas nega o que sabe.","não há aumento de pena se a prova for destinada a gerar efeito em juízo arbitral."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT6/TRT 6/2013 • TEC 184075","source":"FCC - JT TRT6/TRT 6/2013","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/184075","year":2013,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-150299","sourceQuestionId":"150299","t":"pen-m12","moduleId":"pen-m12","q":"O crime de falso testemunho","o":["pode ser praticado de forma culposa quando o agente foi negligente na observação dos fatos.","não se caracteriza quando versar sobre tema acessório ou impertinente ao objeto do processo.","pode ter como sujeito ativo a vítima, nos crimes de ação penal pública.","pode ter como sujeito ativo o querelante, nos crimes de ação penal privada.","deixa de ser punível se ocorrer retratação após a sentença de primeiro grau e antes do julgamento do recurso."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Of Just (TJ PE)/TJ PE/2012 • TEC 150299","source":"FCC - Of Just (TJ PE)/TJ PE/2012","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/150299","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-187349","sourceQuestionId":"187349","t":"pen-m12","moduleId":"pen-m12","q":"A retratação do agente, antes da sentença no processo em que ocorreu o falso testemunho, é causa","o":["de exclusão da imputabilidade.","de extinção da punibilidade.","de diminuição da pena.","de exclusão da culpabilidade.","supralegal de exclusão da ilicitude."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT11/TRT 11/2012 • TEC 187349","source":"FCC - JT TRT11/TRT 11/2012","subject":"Direito Penal - Falso Testemunho ou Falsa Perícia (arts. 342 e 343 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/187349","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3543891","sourceQuestionId":"3543891","t":"pen-m12","moduleId":"pen-m12","q":"Ryana, advogada da União, ajuizou ação de execução fiscal contra uma empresa situada no Estado do Paraná. Após a regular citação da empresa executada, o seu representante legal, Rodolfo, vai até a porta do edifício onde Ryana mora e quando ela está saindo ele a surpreende, portando uma arma de fogo, exigindo, mediante ameaça, que ela desista da demanda proposta. Ryana registra Boletim de Ocorrência na repartição policial mais próxima. Nesse caso hipotético, Rodolfo cometeu crime, em tese, de","o":["coação no curso do processo.","fraude processual.","favorecimento pessoal.","tráfico de influência.","usurpação de função pública."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025 • TEC 3543891","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Penal - Coação no Curso do Processo (art. 344 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3543891","year":2025,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-105474","sourceQuestionId":"105474","t":"pen-m12","moduleId":"pen-m12","q":"O crime de coação no curso do processo","o":["não se caracteriza quando da violência empregada contra testemunha para forçá-la a não dizer a verdade não resultaram lesões corporais.","só pode ser praticado pelas partes, jamais por estranhos à relação processual ou pelo advogado de qualquer delas.","exige apenas o dolo genérico, sendo desnecessária a finalidade de favorecer interesse próprio ou alheio.","não se caracteriza quando o autor do delito ameaça de morte o escrivão de polícia no curso do inquérito policial, com o fim de impedir o seu indiciamento.","consuma-se com a prática da violência ou grave ameaça, pouco importando se o agente conseguiu ou não a abstenção ou omissão da vítima em declarar ou apurar a verdade."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Cons Sub Aud (TCE SP)/TCE SP/2013 • TEC 105474","source":"FCC - Cons Sub Aud (TCE SP)/TCE SP/2013","subject":"Direito Penal - Coação no Curso do Processo (art. 344 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/105474","year":2013,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-205693","sourceQuestionId":"205693","t":"pen-m12","moduleId":"pen-m12","q":"Configura o crime de coação no curso do processo o uso de violência ou grave ameaça, com o fim de favorecer interesse próprio ou alheio, contra autoridade, parte, ou qualquer outra pessoa que funciona ou é chamada a intervir em","o":["processo judicial, havendo aumento da pena se ocorrer em feito penal.","processo administrativo, mas não em inquérito policial.","processo judicial de qualquer natureza, mas não em processo administrativo.","juízo arbitral.","inquérito policial e apenas em processo judicial penal."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT18/TRT 18/2012 • TEC 205693","source":"FCC - JT TRT18/TRT 18/2012","subject":"Direito Penal - Coação no Curso do Processo (art. 344 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/205693","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-204750","sourceQuestionId":"204750","t":"pen-m12","moduleId":"pen-m12","q":"No crime de exercício arbitrário das próprias razões, a ação penal é","o":["sempre pública condicionada.","privada, se não há emprego de violência.","sempre privada.","pública condicionada, se não há emprego de violência.","sempre pública incondicionada."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT18/TRT 18/2014 • TEC 204750","source":"FCC - JT TRT18/TRT 18/2014","subject":"Direito Penal - Exercício Arbitrário das Próprias Razões (arts. 345 e 346 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/204750","year":2014,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2638073","sourceQuestionId":"2638073","t":"pen-m12","moduleId":"pen-m12","q":"Com relação ao crime de \"Exercício arbitrário das próprias razões”, considere o artigo 345 do Código Penal: Art. 345 - ...... justiça pelas próprias mãos, para satisfazer ...... , embora ...... , salvo quando ...... o permite. Completa correta e, respectivamente, as lacunas da definição do tipo penal:","o":["Fazer − objetivo − ilegítima − o juiz","Fazer − pretensão − legítima − a lei","Buscar − pretensão − lícita − o juiz","Fazer − pretensão − lícita − o juiz","Buscar − dívida − legal − a lei"],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014 • TEC 2638073","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014","subject":"Direito Penal - Exercício Arbitrário das Próprias Razões (arts. 345 e 346 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2638073","year":2014,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-526774","sourceQuestionId":"526774","t":"pen-m12","moduleId":"pen-m12","q":"Roberto e Ronaldo, ambos policiais militares, em patrulhamento em um bairro violento, abordam João que, ao perceber a aproximação da polícia, imediatamente levanta as mãos para o alto. Um dos policiais, assustado com a reação abrupta de João, realiza um disparo de arma de fogo contra ele, vindo a matá-lo. Diante da situação, os policiais colocam uma outra arma de fogo nas mãos da vítima baleada e atiram com ela para o alto, simulando um confronto. Além de eventual prática de homicídio, os policiais militares poderão ainda ser processados pelo crime de","o":["fraude processual.","exercício arbitrário das próprias razões.","autoacusação falsa.","favorecimento pessoal.","desobediência."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Sold (PM)/PM AP/2017 • TEC 526774","source":"FCC - Sold (PM)/PM AP/2017","subject":"Direito Penal - Fraude Processual (art. 347 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/526774","year":2017,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-171877","sourceQuestionId":"171877","t":"pen-m12","moduleId":"pen-m12","q":"Para incluir-se no âmbito de proteção normativa do artigo 347 do Código Penal, a inovação da coisa na pendência de processo notadamente precisa ser","o":["cênica e/ou ardilosa.","importante e/ou significativa.","voluntária e/ou consciente.","oculta e/ou sub-reptícia.","irreversível e/ou irreparável."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRF3/TRF 3/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 171877","source":"FCC - AJ TRF3/TRF 3/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Penal - Fraude Processual (art. 347 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/171877","year":2014,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-150511","sourceQuestionId":"150511","t":"pen-m12","moduleId":"pen-m12","q":"A respeito do crime de fraude processual, é INCORRETO afirmar que","o":["pode ser praticado por qualquer pessoa, ainda que não interessada na solução do processo.","pode ser praticado pelo procurador de qualquer das partes.","é punido com detenção e sanção pecuniária na modalidade culposa.","pode ocorrer em processo civil, penal e até em processo administrativo.","é admissível a tentativa, pois a conduta descrita no tipo é fracionável."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TJ PE)/TJ PE/Judiciária e Administrativa/2012 • TEC 150511","source":"FCC - AJ (TJ PE)/TJ PE/Judiciária e Administrativa/2012","subject":"Direito Penal - Fraude Processual (art. 347 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/150511","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1568936","sourceQuestionId":"1568936","t":"pen-m12","moduleId":"pen-m12","q":"Manoel cometeu cinco crimes de homicídio em uma pequena cidade do Estado do Amapá e passou a ser procurado pela Justiça Pública, ainda na fase investigatória, após ter a sua prisão temporária decretada. Para que não seja capturado pela polícia, Manoel contratou seu amigo João, renomado cirurgião plástico, que realizou em Manoel uma operação plástica, alterando completamente o rosto do criminoso. Neste caso, João, ciente do intuito de Manuel, cometeu crime de","o":["inutilização de sinal.","favorecimento pessoal.","tergiversação.","fraude processual.","favorecimento real."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Ana Min (MPE AP)/MPE AP/Direito/2012 • TEC 1568936","source":"FCC - Ana Min (MPE AP)/MPE AP/Direito/2012","subject":"Direito Penal - Fraude Processual (art. 347 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1568936","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-120544","sourceQuestionId":"120544","t":"pen-m12","moduleId":"pen-m12","q":"José percebeu que seu conhecido João havia cometido crime de desobediência e estava fugindo a pé, sendo perseguido por policiais. Em vista disso, despistou os milicianos e colocou João no interior de seu veículo, deixando o local e impedindo, dessa forma, a prisão em flagrante deste. Nesse caso, José responderá pelo crime de","o":["favorecimento pessoal privilegiado.","favorecimento real.","favorecimento pessoal em seu tipo fundamental.","arrebatamento de preso.","facilitar a fuga de pessoa presa."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRF2/TRF 2/Judiciária/\"Sem Especialidade\"/2012 • TEC 120544","source":"FCC - AJ TRF2/TRF 2/Judiciária/\"Sem Especialidade\"/2012","subject":"Direito Penal - Favorecimento Pessoal (art. 348 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/120544","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-181776","sourceQuestionId":"181776","t":"pen-m12","moduleId":"pen-m12","q":"O crime de favorecimento pessoal","o":["só se configura se o agente auxiliar a subtrair-se à ação de autoridade pública autor de crime a que é cominada pena de reclusão.","tipifica-se quando o agente prestar auxílio para iludir as investigações do delito.","pode ser cometido por omissão, como quando o agente não comunica à autoridade o paradeiro do favorecido.","não se caracteriza quando alguém dificultar a investigação da autoridade ou de seus agentes.","não se caracteriza quando o agente auxiliar o criminoso a fugir após a perpetração do delito."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Proc (João Pessoa)/Pref João Pessoa/2012 • TEC 181776","source":"FCC - Proc (João Pessoa)/Pref João Pessoa/2012","subject":"Direito Penal - Favorecimento Pessoal (art. 348 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/181776","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-547768","sourceQuestionId":"547768","t":"pen-m12","moduleId":"pen-m12","q":"Patrícia, ao visitar seu companheiro Jorge, que cumpre pena em regime fechado pela prática de crime de roubo, tenta ingressar no estabelecimento prisional trazendo consigo um aparelho de telefone celular que seria entregue a Jorge, ocasião em que é surpreendida pelos agentes penitenciários no momento da revista. Considerando a situação hipotética,","o":["o fato praticado por Patrícia é atípico.","Patrícia não praticou qualquer crime.","Patrícia não praticou qualquer crime. Jorge, contudo, praticou falta grave prevista na Lei de Execuções Penais.","Patrícia, embora tenha praticado fato típico, previsto no Código Penal, por ser companheira de Jorge, é isenta de pena.","o fato praticado por Patrícia é crime punido com detenção."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Ag Pol (PC AP)/PC AP/2017 • TEC 547768","source":"FCC - Ag Pol (PC AP)/PC AP/2017","subject":"Direito Penal - Favorecimento Real (arts. 349 e 349-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/547768","year":2017,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-283579","sourceQuestionId":"283579","t":"pen-m12","moduleId":"pen-m12","q":"João subtraiu valores em dinheiro do caixa da repartição pública em que trabalhava. José, após a prática do delito, a pedido de João, escondeu o dinheiro no cofre de sua empresa, para tornar seguro o proveito do crime por este cometido. Nesse caso, José responderá pelo crime de","o":["peculato culposo.","peculato doloso.","favorecimento pessoal.","favorecimento real.","fraude processual."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - ACI (CGM São Luís)/Pref São Luís/Engenharia Elétrica/2015 • TEC 283579","source":"FCC - ACI (CGM São Luís)/Pref São Luís/Engenharia Elétrica/2015","subject":"Direito Penal - Favorecimento Real (arts. 349 e 349-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/283579","year":2015,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-271241","sourceQuestionId":"271241","t":"pen-m12","moduleId":"pen-m12","q":"Tício subtraiu um veículo automóvel e o levou até a oficina de Cezar, que modificou as placas identificadoras para assegurar-lhe a posse do produto do crime. Nesse caso, Cezar responderá por","o":["furto.","favorecimento real.","favorecimento pessoal.","receptação.","estelionato."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Adv Jr (METRO SP)/METRO SP/2014 • TEC 271241","source":"FCC - Adv Jr (METRO SP)/METRO SP/2014","subject":"Direito Penal - Favorecimento Real (arts. 349 e 349-A do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/271241","year":2014,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-153890","sourceQuestionId":"153890","t":"pen-m12","moduleId":"pen-m12","q":"João e José invadiram um presídio e, mediante grave ameaça com armas de fogo, dominaram o carcereiro e os seguranças e possibilitaram a fuga de seu comparsa Jocival, que estava legalmente preso cumprindo pena privativa de liberdade, para que o mesmo voltasse a auxiliá-los na prática de novos delitos. João e José responderão por crime de","o":["arrebatamento de preso.","evasão mediante violência contra pessoa.","fuga de pessoa presa.","motim de presos.","favorecimento real."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE RO/TRE RO/Judiciária/2013 • TEC 153890","source":"FCC - AJ TRE RO/TRE RO/Judiciária/2013","subject":"Direito Penal - Fuga de Pessoa Presa ou Submetida a Medida de Segurança (art. 351 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/153890","year":2013,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-150507","sourceQuestionId":"150507","t":"pen-m12","moduleId":"pen-m12","q":"Paulus foi preso em flagrante e recolhido à cadeia pública de uma cidade do interior. No momento da alimentação, mediante violência física, dominou o carcereiro e tentou fugir, mas, na porta da delegacia, foi dominado por policiais que estavam chegando ao local. Paulus responderá por crime de","o":["arrebatamento de preso, na forma consumada.","evasão mediante violência contra pessoa, na forma consumada.","motim de presos, na forma consumada.","evasão mediante violência contra pessoa, na forma tentada.","fuga de pessoa presa, na forma tentada."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TJ PE)/TJ PE/Judiciária e Administrativa/2012 • TEC 150507","source":"FCC - AJ (TJ PE)/TJ PE/Judiciária e Administrativa/2012","subject":"Direito Penal - Evasão mediante Violência contra a Pessoa (art. 352 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/150507","year":2012,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-86956","sourceQuestionId":"86956","t":"pen-m12","moduleId":"pen-m12","q":"Arrebatamento de preso é classificado como crime","o":["de abuso de autoridade.","praticado por particular contra a administração em geral.","praticado por funcionário público contra a administração em geral.","contra a fé pública.","contra a administração da Justiça."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRE TO/TRE TO/Judiciária/2011 • TEC 86956","source":"FCC - AJ TRE TO/TRE TO/Judiciária/2011","subject":"Direito Penal - Arrebatamento de Preso (art. 353 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/86956","year":2011,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-714203","sourceQuestionId":"714203","t":"pen-m12","moduleId":"pen-m12","q":"A conduta de solicitar dinheiro a pretexto de influir em órgão do Ministério Público, nos termos do Código Penal, configura o crime de","o":["fraude processual.","tergiversação.","corrupção passiva.","exploração de prestígio.","tráfico de influência."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Prom Jus (MPE PB)/MPE PB/2018 • TEC 714203","source":"FCC - Prom Jus (MPE PB)/MPE PB/2018","subject":"Direito Penal - Exploração de Prestígio (art. 357 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/714203","year":2018,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-85879","sourceQuestionId":"85879","t":"pen-m12","moduleId":"pen-m12","q":"Maria procurou Ana, que ia ser submetida a julgamento perante o Tribunal do Júri por crime de infanticídio e, dizendo-se amiga de dois jurados, solicitou a quantia de R$ 5.000,00 para influir a seu favor no julgamento destes. Maria responderá por crime de","o":["estelionato.","corrupção ativa.","exploração de prestígio.","advocacia administrativa.","favorecimento pessoal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TJ TRT1/TRT 1/Administrativa/Agente da Policia Judicial/2011 • TEC 85879","source":"FCC - TJ TRT1/TRT 1/Administrativa/Agente da Policia Judicial/2011","subject":"Direito Penal - Exploração de Prestígio (art. 357 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/85879","year":2011,"caderno":6,"classificationReason":"Crime situado no Título dos crimes contra a Administração Pública.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1147343","sourceQuestionId":"1147343","t":"pen-m12","moduleId":"pen-m12","q":"Constitui crime de","o":["tráfico de influência, delito contra a administração da justiça, solicitar ou receber dinheiro ou qualquer outra utilidade, a pretexto de influir em juiz, jurado, órgão do Ministério Público, funcionário da justiça, perito, tradutor, intérprete ou testemunha.","tergiversação, delito contra a administração da justiça, o ato do advogado ou procurador judicial que defende na mesma causa, sucessivamente, partes contrárias.","exploração de prestígio, delito praticado por particular contra a administração em geral, solicitar, exigir, cobrar ou obter, para si ou para outrem, vantagem ou promessa de vantagem, a pretexto de influir em ato praticado por funcionário público no exercício da função.","patrocínio infiel, delito praticado por funcionário púbico contra a administração em geral, patrocinar, direta ou indiretamente, interesse privado perante a administração pública, valendo-se da qualidade de funcionário.","favorecimento real, delito contra a administração da justiça, auxiliar a subtrair-se à ação de autoridade pública autor de crime a que é cominada pena de reclusão."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JE TJMS/TJ MS/2020 • TEC 1147343","source":"FCC - JE TJMS/TJ MS/2020","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1147343","year":2020,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-638739","sourceQuestionId":"638739","t":"pen-m12","moduleId":"pen-m12","q":"São, dentre outros, crimes contra a administração da Justiça:","o":["resistência, desobediência, desacato e tráfico de influência.","advocacia administrativa, condescendência criminosa, violação de sigilo funcional e abandono de função.","auto-acusação falsa, exercício arbitrário das próprias razões, denunciação caluniosa e exploração de prestígio.","falsidade ideológica, falso reconhecimento de firma ou letra, certidão ou atestado ideologicamente falso e adulteração de sinal identificador de veículo automotor.","concussão, corrupção passiva, prevaricação e corrupção ativa."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Ana Leg (ALESE)/ALESE/Apoio Técnico ao Processo Legislativo/Processo Legislativo/2018 • TEC 638739","source":"FCC - Ana Leg (ALESE)/ALESE/Apoio Técnico ao Processo Legislativo/Processo Legislativo/2018","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/638739","year":2018,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-264796","sourceQuestionId":"264796","t":"pen-m12","moduleId":"pen-m12","q":"No que toca aos crimes contra a administração da justiça, acertado afirmar que","o":["não configura crime a conduta de provocar a ação de autoridade, comunicando-lhe a ocorrência de contravenção que sabe não se ter verificado.","configura favorecimento pessoal a conduta de auxiliar a subtrair-se à ação de autoridade pública autor de crime a que é cominada pena de detenção.","não configura denunciação caluniosa dar causa à instauração de investigação policial contra alguém, imputando-lhe contravenção penal de que o sabe inocente.","configura o crime de autoacusação falsa a conduta de acusar-se, perante a autoridade, de contravenção penal inexistente ou praticada por outrem.","não configura coação no curso do processo usar de violência ou grave ameaça, com o fim de favorecer interesse próprio ou alheio, contra autoridade, parte, ou qualquer outra pessoa que funciona ou é chamada a intervir em juízo arbitral."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JE TJGO/TJ GO/2015 • TEC 264796","source":"FCC - JE TJGO/TJ GO/2015","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/264796","year":2015,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-300673","sourceQuestionId":"300673","t":"pen-m12","moduleId":"pen-m12","q":"Quanto aos crimes contra a administração da justiça,","o":["não tipifica denunciação caluniosa dar causa à instauração de investigação policial ou de processo judicial contra alguém, imputando-lhe contravenção penal de que o sabe inocente.","qualquer pessoa pode ser sujeito ativo do delito de sonegação de papel ou objeto de valor probatório.","configura o delito de favorecimento pessoal o ato de auxiliar a subtrair-se à ação de autoridade pública autor de crime a que for cominada pena de detenção.","há tergiversação quando o advogado defende na mesma causa, simultaneamente, partes contrárias.","só o advogado pode ser sujeito ativo dos delitos de patrocínio infiel e exploração de prestígio."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT15/TRT 15/2015 • TEC 300673","source":"FCC - JT TRT15/TRT 15/2015","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/300673","year":2015,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-250886","sourceQuestionId":"250886","t":"pen-m12","moduleId":"pen-m12","q":"No que concerne aos crimes contra a Administração da Justiça, é correto afirmar que","o":["constitui crime de exploração de prestígio patrocinar, direta ou indiretamente, interesse privado perante a administração pública, valendo-se da qualidade de funcionário.","há delito de tergiversação se o advogado ou procurador judicial, sucessivamente, passa a defender na mesma causa interesses de partes contrárias.","constitui crime de patrocínio infiel solicitar, exigir, cobrar ou obter, para si ou para outrem, vantagem ou promessa de vantagem, a pretexto de influir em ato praticado por funcionário público no exercício da função.","impedir arrematação judicial apenas constitui crime se houver fraude ou oferecimento de vantagem.","constitui favorecimento pessoal prestar a criminoso, fora dos casos de coautoria ou receptação, auxílio destinado a tornar seguro o proveito do crime."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT24/TRT 24/2014 • TEC 250886","source":"FCC - JT TRT24/TRT 24/2014","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/250886","year":2014,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2638072","sourceQuestionId":"2638072","t":"pen-m12","moduleId":"pen-m12","q":"Referente aos crimes contra a Administração da Justiça, é correto afirmar que o crime de","o":["denunciação caluniosa é cometido por aquele que provoca a ação de autoridade, comunicando-lhe a ocorrência de crime ou de contravenção que sabe não se ter verificado.","comunicação falsa de crime ou de contravenção é cometido por aquele que dá causa à instauração de investigação policial, de processo judicial, instauração de investigação administrativa, inquérito civil ou ação de improbidade administrativa contra alguém, imputando- lhe crime de que o sabe inocente.","falso testemunho ou perícia é conduta atípica se praticado em juízo arbitral.","autoacusação falsa, ocorre quando o sujeito ativo acusa-se, perante a autoridade, de crime inexistente, sendo que se a autoacusação tratar-se de crime praticado por outrem, o crime será de calúnia.","coação no curso do processo pode ocorrer em processo judicial, policial, administrativo, ou em juízo arbitral."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014 • TEC 2638072","source":"FCC - AJ (TJ AP)/TJ AP/Judiciária/Execução de Mandados/2014","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2638072","year":2014,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-121275","sourceQuestionId":"121275","t":"pen-m12","moduleId":"pen-m12","q":"Em relação aos crimes contra a administração pública, correto afirmar que","o":["é atípica a conduta de acusar-se, perante a autoridade, de contravenção penal inexistente ou praticada por outrem.","configura favorecimento pessoal o ato de prestar a criminoso, fora dos casos de coautoria ou de receptação, auxílio destinado a tornar seguro o proveito do crime.","o falso testemunho deixa de ser punível se, depois da sentença em que ocorreu o ilícito, o agente se retrata ou declara a verdade.","o crime de concussão é de natureza formal, reclamando o recebimento da vantagem para a consumação.","é pública condicionada a ação penal no delito de exercício arbitrário das próprias razões, se não há emprego de violência."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JE TJPE/TJ PE/2013 • TEC 121275","source":"FCC - JE TJPE/TJ PE/2013","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/121275","year":2013,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-85074","sourceQuestionId":"85074","t":"pen-m12","moduleId":"pen-m12","q":"NÃO constitui crime contra a administração da justiça","o":["a denunciação caluniosa.","o exercício arbitrário das próprias razões.","o favorecimento pessoal.","o patrocínio infiel.","a desobediência."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT1/TRT 1/2012 • TEC 85074","source":"FCC - JT TRT1/TRT 1/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/85074","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-116722","sourceQuestionId":"116722","t":"pen-m12","moduleId":"pen-m12","q":"No tocante aos crimes contra a administração da justiça, é correto afirmar que","o":["não se tipifica o delito de coação no curso do processo se o agente, com o fim de favorecer interesse alheio, usar de violência ou grave ameaça, contra pessoa que é chamada a intervir em processo judicial.","a pena é aumentada de sexta parte, na denunciação caluniosa, se o agente se serve do anonimato ou de nome suposto.","tipifica o delito de autoacusação falsa o ato de acusar-se, perante a autoridade, de contravenção penal inexistente ou praticada por outrem.","a pena sempre deve ser aumentada se a fraude processual se destina a produzir efeito em processo civil.","só configura o delito de favorecimento pessoal o ato de auxiliar a subtrair-se à ação de autoridade pública autor de crime a que for cominada pena de reclusão."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT4/TRT 4/2012 • TEC 116722","source":"FCC - JT TRT4/TRT 4/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/116722","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-120572","sourceQuestionId":"120572","t":"pen-m12","moduleId":"pen-m12","q":"A respeito dos Crimes contra a Administração Pública, considere: I. O preso que foge do presídio, aproveitando-se de um descuido dos policiais, não responde por nenhum delito relacionado à sua fuga. II. A ação de várias pessoas, retirando, mediante violência, pessoa presa da guarda da escolta que o tinha sob custódia, para fins de linchamento, caracteriza o delito de arrebatamento de preso. III. A conduta do preso que permite ao seu companheiro de cela assumir sua identidade e assim se apresentar ao carcereiro encarregado de dar cumprimento a alvará de soltura, logrando êxito em fugir, não comete nenhum delito, pela ausência de grave ameaça ou violência à pessoa. Está correto o que consta SOMENTE em","o":["III.","I e III.","II e III.","I.","I e II."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TJ TRF2/TRF 2/Administrativa/Agente da Policia Judicial/2012 • TEC 120572","source":"FCC - TJ TRF2/TRF 2/Administrativa/Agente da Policia Judicial/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/120572","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-376963","sourceQuestionId":"376963","t":"pen-m12","moduleId":"pen-m12","q":"Pedro, menor de dezessete anos, comete um ato infracional equiparado a crime de roubo contra um supermercado, empreendendo fuga logo em seguida. José, seu melhor amigo, de 22 anos de idade, deixa Pedro ingressar em sua residência e ali permanecer por alguns dias, impedindo a ação da Polícia. Neste caso, José","o":["cometeu crime de tráfico de influência.","cometeu crime de favorecimento pessoal.","não cometeu nenhum crime.","cometeu crime de favorecimento real.","cometeu crime de fraude processual."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TRE CE)/TRE CE/Judiciária/2012 • TEC 376963","source":"FCC - AJ (TRE CE)/TRE CE/Judiciária/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/376963","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-385794","sourceQuestionId":"385794","t":"pen-m12","moduleId":"pen-m12","q":"Nos crimes contra a administração da justiça,","o":["a pena sempre deve ser aumentada se a falsa perícia for cometida com o fim de obter prova destinada a produzir efeito em processo trabalhista.","é pública condicionada a ação penal no crime de exercício arbitrário das próprias razões.","a pena será diminuída se a imputação, na denunciação caluniosa, for de prática de contravenção penal.","configura o delito de favorecimento pessoal o ato de prestar a criminoso, fora dos casos de coautoria ou receptação, auxílio destinado a tornar seguro o proveito do crime.","só funcionário público pode ser sujeito ativo do delito de exploração de prestígio."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - JT TRT20/TRT 20/2012 • TEC 385794","source":"FCC - JT TRT20/TRT 20/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/385794","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-687415","sourceQuestionId":"687415","t":"pen-m12","moduleId":"pen-m12","q":"Considere: I. Facilitar a fuga de pessoa legalmente presa. II. Auxiliar a subtrair-se à ação de autoridade pública o autor de crime a que é cominada pena de reclusão. Essas condutas tipificam, respectivamente, os delitos de","o":["arrebatamento de preso e favorecimento real.","fuga de pessoa presa ou submetida à medida de segurança e favorecimento pessoal.","motim de presos e favorecimento real.","condescendência criminosa e favorecimento pessoal.","arrebatamento de preso e favorecimento pessoal."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Tec Min (MPE PE)/MPE PE/Apoio Especializado/Contabilidade/2012 • TEC 687415","source":"FCC - Tec Min (MPE PE)/MPE PE/Apoio Especializado/Contabilidade/2012","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/687415","year":2012,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-23680","sourceQuestionId":"23680","t":"pen-m12","moduleId":"pen-m12","q":"Quanto aos crimes contra a administração da justiça, é correto afirmar que","o":["não configura o crime de coação no curso do processo o uso de violência ou grave ameaça contra testemunha em processo administrativo, com o fim de favorecer interesse próprio ou alheio.","as penas são aumentadas de um terço no delito de exploração de prestígio, se o agente insinua que o dinheiro solicitado, a pretexto de influir em testemunha, a esta também se destina.","constitui favorecimento pessoal prestar a criminoso, fora dos casos de coautoria ou receptação, auxílio destinado a tornar seguro o proveito do crime.","configura o delito de auto-acusação falsa o ato da pessoa que, perante a autoridade, se atribui o cometimento de contravenção penal inexistente ou praticada por outrem.","não incorre nas penas do delito de patrocínio infiel o advogado que defende na mesma causa, simultânea ou sucessivamente, partes contrárias."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Proc (MP TCE-SP)/TCE SP/2011 • TEC 23680","source":"FCC - Proc (MP TCE-SP)/TCE SP/2011","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/23680","year":2011,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-65243","sourceQuestionId":"65243","t":"pen-m12","moduleId":"pen-m12","q":"A respeito dos Crimes contra a Administração da Justiça, considere: I. No delito de comunicação falsa de crime ou contravenção, há indicação expressa de pessoa determinada como autora da infração. II. No delito de denunciação caluniosa, não há indicação expressa de determinada pessoa como autora da infração. III. A vítima de um crime não comete crime de falso testemunho se calar a verdade em processo judicial. IV. No delito de falso testemunho, o fato deixa de ser punível se o agente se retrata ou declara a verdade até o trânsito em julgado da sentença ou do acórdão proferido no processo em que ocorreu a falsidade. Está correto o que se afirma SOMENTE em:","o":["III.","I, II e III.","I e IV.","II, III e IV.","I, II e IV."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ (TRF 1ª Região)/TRF 1/Judiciária/Oficial de Justiça Avaliador Federal/2011 • TEC 65243","source":"FCC - AJ (TRF 1ª Região)/TRF 1/Judiciária/Oficial de Justiça Avaliador Federal/2011","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/65243","year":2011,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-85881","sourceQuestionId":"85881","t":"pen-m12","moduleId":"pen-m12","q":"A respeito dos crimes contra a Administração da Justiça considere: I. Não constitui crime a conduta de acusar-se perante a autoridade de crime praticado por outrem. II. Não comete crime de falso testemunho a testemunha que simplesmente calar a verdade. III. Quem, na pendência de processo civil, altera o local dos fatos com o fim de induzir em erro o perito, comete crime de fraude processual. Está correto o que se afirma APENAS em","o":["I.","I e II.","I e III.","II e III.","III."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TJ TRT1/TRT 1/Administrativa/Agente da Policia Judicial/2011 • TEC 85881","source":"FCC - TJ TRT1/TRT 1/Administrativa/Agente da Policia Judicial/2011","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração da Justiça (arts. 338 a 359 do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/85881","year":2011,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3821984","sourceQuestionId":"3821984","t":"pen-m17","moduleId":"pen-m17","q":"Considere os seguintes casos hipotéticos: I. Paulo, Prefeito de um Município do Estado de Pernambuco, executa ato que acarreta aumento de despesa total com pessoal, faltando nove meses para o término do seu mandato. II. Ricardo, Presidente da Câmara Municipal de determinado município pernambucano, autoriza ato que acarreta aumento de despesa total com pessoal faltando cinco meses para o término da sua legislatura. III. Ronaldo, Presidente da Assembleia Legislativa de um determinado Estado da Federação, faltando 12 meses para o término do seu mandato, ordena ato que acarreta aumento de despesa total com pessoal. IV. Maurílio, Governador de um determinado Estado da Federação, faltando sete meses para o término do seu mandato, executa ato que acarreta aumento de despesa total com pessoal. Nos termos preconizados pelo Código Penal, após a entrada em vigor da Lei nº 10.028/2000, que previu os Crimes contra as Finanças Públicas, o crime de “Aumento de despesa total com pessoal no último ano do mandato ou legislatura” foi praticado, em tese, por","o":["Paulo, Ricardo e Maurílio, apenas.","Paulo e Ricardo, apenas.","Ricardo, apenas.","Paulo, Ricardo, Ronaldo e Maurílio.","Ricardo e Maurílio, apenas."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026 • TEC 3821984","source":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3821984","year":2026,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3930776","sourceQuestionId":"3930776","t":"pen-m17","moduleId":"pen-m17","q":"Comete o crime de “aumento de despesa total com pessoal no último ano do mandato ou legislatura” o gestor que aumentar o gasto de pessoal nos últimos","o":["120 dias de mandato, independente de existir disponibilidade de caixa.","365 dias de mandato, desde que não haja disponibilidade de caixa.","240 dias de mandato, independente de existir disponibilidade de caixa.","180 dias de mandato, independente de existir disponibilidade de caixa.","60 dias de mandato, desde que não haja disponibilidade de caixa."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - ALegis (ALMS)/ALMS/Controle Interno/2026 • TEC 3930776","source":"FCC - ALegis (ALMS)/ALMS/Controle Interno/2026","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3930776","year":2026,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3975736","sourceQuestionId":"3975736","t":"pen-m17","moduleId":"pen-m17","q":"Há crime contra as finanças públicas (art. 359-A a 359-H, do Código Penal) na conduta do administrador que","o":["realiza operação de crédito, interno ou externo com inobservância de limite, condição ou montante estabelecido em lei ou em resolução da Câmara dos Deputados.","deixa de ordenar, de autorizar ou de promover o cancelamento do montante de restos a pagar inscrito em valor inferior ao permitido em lei.","ao efetuar operação de crédito em que seja exigida garantia do poder público, não exige contragarantia em valor igual ou maior.","ordena ato que acarrete aumento de despesa total com pessoal, nos trezentos e sessenta dias anteriores ao final do mandato ou da legislatura.","autoriza a assunção de obrigação, nos três últimos quadrimestres do último ano do mandato ou legislatura, cuja despesa não possa ser paga no mesmo exercício financeiro."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - AFRE GO/SEFAZ GO/2026 • TEC 3975736","source":"FCC - AFRE GO/SEFAZ GO/2026","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3975736","year":2026,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-660046","sourceQuestionId":"660046","t":"pen-m17","moduleId":"pen-m17","q":"São crimes contra as finanças públicas previstos no Código Penal:","o":["contratação de operação de crédito; violência ou fraude em arrematação judicial e favorecimento real.","ordenação de despesa não autorizada; não cancelamento de restos a pagar e prestação de garantia graciosa.","inscrição de despesas não empenhadas em restos a pagar; corrupção ativa e excesso de exação.","aumento de despesa total com pessoal no último ano do mandato ou legislatura; emprego irregular de verbas ou rendas públicas e concussão.","oferta pública ou colocação de títulos no mercado; falso testemunho ou falsa perícia e favorecimento pessoal."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - AFT I (Pref São Luís)/Pref São Luís/Abrangência Geral/2018 • TEC 660046","source":"FCC - AFT I (Pref São Luís)/Pref São Luís/Abrangência Geral/2018","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/660046","year":2018,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-676726","sourceQuestionId":"676726","t":"pen-m17","moduleId":"pen-m17","q":"São condutas típicas dos crimes contra as finanças públicas:","o":["Deixar de ordenar o cancelamento do montante de restos a pagar inscrito em valor superior ao permitido em lei; apropriar-se de dinheiro que, no exercício do cargo público, recebeu por erro de outrem e exigir o funcionário público, em razão da função, tributo que sabe indevido.","Apropriar-se de valor público, de que tenha a posse em razão do cargo; apropriar-se de dinheiro que, no exercício do cargo público, recebeu por erro de outrem; e dar às verbas públicas aplicação diversa da estabelecida em lei.","Exigir em razão da função pública, tributo que sabe indevido; deixar o funcionário público de responsabilizar subordinado que cometeu infração no exercício do cargo; e devassar o sigilo de proposta de concorrência pública.","Autorizar operação de crédito sem prévia autorização legislativa; ordenar despesa não autorizada por lei; e deixar de promover o cancelamento do montante de restos a pagar inscrito em valor superior ao permitido em lei.","Deixar o funcionário público de responsabilizar subordinado que cometeu infração no exercício do cargo; dar às verbas públicas aplicação diversa da estabelecida em lei; e apropriar-se de valor público, de que tenha a posse em razão da função pública."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - APE (TCE-RS)/TCE RS/Ciências Jurídicas e Sociais, Direito/2018 • TEC 676726","source":"FCC - APE (TCE-RS)/TCE RS/Ciências Jurídicas e Sociais, Direito/2018","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/676726","year":2018,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-362401","sourceQuestionId":"362401","t":"pen-m17","moduleId":"pen-m17","q":"A contratação, em nome do Município, de operação de crédito sem autorização legislativa constitui crime contra","o":["a ordem econômica.","as finanças públicas.","a economia popular.","o patrimônio público.","a ordem tributária."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - Proc (Pref Campinas)/Pref Campinas/2016 • TEC 362401","source":"FCC - Proc (Pref Campinas)/Pref Campinas/2016","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/362401","year":2016,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-256081","sourceQuestionId":"256081","t":"pen-m17","moduleId":"pen-m17","q":"Com relação ao crime de contratação de operação de crédito (art. 359-A do CP), é correto afirmar:","o":["Comete o crime aquele que ordena, autoriza ou realiza operação de crédito, interno ou externo, ainda que com prévia autorização legislativa.","Comete o crime aquele que ordena ou autoriza operação de crédito, interno ou externo, ainda que com prévia autorização legislativa.","A pena é de detenção de 1 (um) a 2 (dois) anos.","Incide na mesma pena do referido crime aquele que ordenar, autorizar ou realizar operação de crédito, interno ou externo, quando o montante da dívida consolidada excede o limite mínimo autorizado por lei.","Incide na mesma pena do referido crime aquele que ordenar, autorizar ou realizar operação de crédito, interno ou externo, com inobservância de limite, condição ou montante estabelecido em lei ou em resolução do Senado Federal."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015 • TEC 256081","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/256081","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-256084","sourceQuestionId":"256084","t":"pen-m17","moduleId":"pen-m17","q":"Em relação aos crimes contra as finanças públicas, é correto afirmar:","o":["Comete o crime de inscrição de despesas não empenhadas em restos a pagar aquele que ordenar ou autorizar a inscrição em restos a pagar, de despesa que não tenha sido previamente empenhada ou que exceda limite estabelecido em resolução do Senado Federal.","O crime de inscrição de despesas não empenhadas em restos a pagar admite a tentativa.","O tipo previsto no artigo 359-D do Código Penal (ordenação de despesa não autorizada) é crime de mera conduta.","O tipo previsto no artigo 359-D do Código Penal (ordenação de despesa não autorizada) não admite o dolo eventual.","O tipo do artigo 359-B do Código Penal (inscrição de despesas não empenhadas em restos a pagar) admite a modalidade culposa."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015 • TEC 256084","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/256084","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-256087","sourceQuestionId":"256087","t":"pen-m17","moduleId":"pen-m17","q":"No crime de assunção de obrigação no último ano do mandato ou legislatura,","o":["há uma proibição absoluta de assumir obrigação em fim de mandato ou legislatura.","a consumação ocorre com a assunção da obrigação.","a pena é de reclusão de 1 (um) a 5 (cinco) anos.","admite-se forma culposa.","é inadmissível a tentativa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015 • TEC 256087","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/256087","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-256091","sourceQuestionId":"256091","t":"pen-m17","moduleId":"pen-m17","q":"Considere as seguintes afirmativas: I. O crime de prestação de garantia graciosa consuma-se com a ocorrência de prejuízo efetivo para os cofres públicos. II. O crime de prestação de garantia graciosa admite a modalidade culposa. III. O crime de não cancelamento de restos a pagar é crime omissivo puro. IV. Para a consumação do crime de não cancelamento de restos a pagar não se exige que haja prejuízo efetivo para a Administração. Está correto o que se afirma APENAS em","o":["III e IV.","I e IV.","II e IV.","II e III.","I, II e III."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015 • TEC 256091","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/256091","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-256094","sourceQuestionId":"256094","t":"pen-m17","moduleId":"pen-m17","q":"O número de dias anteriores ao final do mandato ou legislatura em que considerar-se-á que incorre no crime de aumento de despesa total com pessoal no último ano do mandato ou legislatura aquele que ordenar, autorizar ou executar ato que acarrete aumento de despesa total com pessoal, conforme legislação vigente, é","o":["cento e vinte.","trezentos e sessenta.","cento e cinquenta.","noventa.","cento e oitenta."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015 • TEC 256094","source":"FCC - AFFE (SEFAZ PI)/SEFAZ PI/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/256094","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-256393","sourceQuestionId":"256393","t":"pen-m17","moduleId":"pen-m17","q":"No crime de ordenar despesas não autorizadas por lei","o":["o sujeito passivo é a fazenda pública.","o sujeito ativo é o agente político que ordena a despesa.","a objetividade jurídica é a probidade administrativa.","o tipo subjetivo é exclusivamente doloso, sendo suficiente o dolo genérico.","o iter criminis deve ter conotação econômica."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - ATE (SEFAZ PI)/SEFAZ PI/2015 • TEC 256393","source":"FCC - ATE (SEFAZ PI)/SEFAZ PI/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/256393","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-283580","sourceQuestionId":"283580","t":"pen-m17","moduleId":"pen-m17","q":"O crime de Inscrição de Despesas Não Empenhadas em Restos a pagar","o":["é punível na forma culposa, com pena reduzida.","admite a tentativa.","é de mera conduta.","só se consuma com a efetiva inscrição da despesa.","só se consuma com a ocorrência de efetivo prejuízo para o Estado."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - ACI (CGM São Luís)/Pref São Luís/Engenharia Elétrica/2015 • TEC 283580","source":"FCC - ACI (CGM São Luís)/Pref São Luís/Engenharia Elétrica/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/283580","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-299596","sourceQuestionId":"299596","t":"pen-m17","moduleId":"pen-m17","q":"O agente público que, possuindo atribuição legal, presta garantia em operação de crédito sem que tenha sido constituída contragarantia em valor igual ou superior ao valor da garantia prestada, pratica crime denominado","o":["prestação de garantia não onerosa.","prestação de garantia graciosa.","contraprestação em operação de crédito.","inscrição de garantia não empenhada em restos a pagar.","assunção de obrigação no último ano do mandato ou legislatura."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - Aud Sub Cons (TCE-AM)/TCE AM/2015 • TEC 299596","source":"FCC - Aud Sub Cons (TCE-AM)/TCE AM/2015","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/299596","year":2015,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-187877","sourceQuestionId":"187877","t":"pen-m17","moduleId":"pen-m17","q":"Estabelece o art. 359-D, do Código Penal, que constitui crime contra as finanças públicas ordenar despesa não autorizada por lei. Tal conduta","o":["cuida-se de crime próprio cujo sujeito ativo somente pode ser o agente público que possui poder e atribuição para ordenar a despesa.","tem como objetividade jurídica a defesa orçamentária da Administração pública direta.","objetiva atingir diretamente o Estado, representado pela União, Estados-membros, Distrito Federal e Municípios e indiretamente os titulares de créditos preferenciais perante a Administração pública.","consuma-se quando a ordem é efetivamente executada, ou seja, quando a despesa ordenada é realmente assumida pelo Poder Público, contrariando previsão legal.","exige ação penal condicionada ao controle orçamentário exercido pelo Tribunal de Contas."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - ACE (TCE-PI)/TCE PI/Jurídica/2014 • TEC 187877","source":"FCC - ACE (TCE-PI)/TCE PI/Jurídica/2014","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/187877","year":2014,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-145664","sourceQuestionId":"145664","t":"pen-m17","moduleId":"pen-m17","q":"O crime, previsto no art. 359-D do Código Penal, com a redação que lhe foi dada pela Lei nº 10.028/2000, “ordenar despesa não autorizada por lei: Pena: reclusão, de 1 (um) a 4 (quatro) anos”","o":["exige a ocorrência de efetivo prejuízo para o Estado.","admite a forma culposa, quando houver imprudência, imperícia ou negligência.","inclui-se dentre os crimes de mera conduta.","não admite a participação de particular.","só pode ser cometido por administrador federal."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - Ana Con (MP TCE-MT)/TCE MT/Direito/2013 • TEC 145664","source":"FCC - Ana Con (MP TCE-MT)/TCE MT/Direito/2013","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/145664","year":2013,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-684068","sourceQuestionId":"684068","t":"pen-m17","moduleId":"pen-m17","q":"No que concerne ao delito de contração de operação de crédito, considere: I. Se o agente público, com atribuições para ordenar operação de crédito, o faz sem prévia autorização legislativa, não chegando, porém, a se concretizar a contratação por circunstâncias alheias à sua vontade, deverá responder pelo delito na forma tentada. II. O sujeito ativo só pode ser agente público, motivo porque é inadmissível a participação criminosa de pessoa que não ostente a qualidade de funcionário público. III. O crime só é punível a título de dolo, não se caracterizando o delito em questão quando a conduta for decorrente de culpa, em quaisquer de suas modalidades. Está correto o que consta SOMENTE em","o":["I e III.","I e II.","III.","II e III.","I."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2012 • TEC 684068","source":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2012","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/684068","year":2012,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-23682","sourceQuestionId":"23682","t":"pen-m17","moduleId":"pen-m17","q":"Constitui crime contra as finanças públicas o ato de ordenar a assunção de obrigação cuja despesa não possa ser paga no exercício financeiro, desde que a determinação ocorra","o":["nos dois últimos quadrimestres do último ano do mandato ou legislatura.","nos dois últimos semestres do último ano do mandato ou legislatura.","nos três últimos trimestres do último ano do mandato ou legislatura.","nos dois últimos quadrimestres dos dois últimos anos do mandato ou legislatura.","nos dois últimos bimestres dos dois últimos anos do mandato ou legislatura."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - Proc (MP TCE-SP)/TCE SP/2011 • TEC 23682","source":"FCC - Proc (MP TCE-SP)/TCE SP/2011","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/23682","year":2011,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-564480","sourceQuestionId":"564480","t":"pen-m17","moduleId":"pen-m17","q":"A prestação por administrador público de garantia em operação de crédito, sem contragarantia em valor igual ou superior ao valor da garantia prestada, quando a lei o exigir,","o":["constitui mera infração administrativa, pois se trata de fato penalmente atípico.","pode representar a prática de crime previsto no Código Penal, além de configurar possível improbidade administrativa.","exige a ocorrência de prejuízo ao erário para ser considerada ato de improbidade administrativa.","é fato típico, desde que demonstrada a negligência da autoridade que a prestou.","caracteriza crime previsto na Lei Geral de Licitações (Lei Federal nº 8.666/93)."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - Proc (MPE TCM-BA)/TCM BA/2011 • TEC 564480","source":"FCC - Proc (MPE TCM-BA)/TCM BA/2011","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/564480","year":2011,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2581938","sourceQuestionId":"2581938","t":"pen-m17","moduleId":"pen-m17","q":"O crime de","o":["contratação de operação de crédito, previsto no art. 359-A, consuma-se com a realização da operação de crédito, interno ou externo, sem prévia autorização do Ministério Público.","aumento de despesa total com pessoal no último ano do mandato ou legislatura, previsto no art. 359-G do Código Penal, só se consuma se houver prejuízo efetivo para a Administração Pública.","não cancelamento de restos a pagar, previsto no art. 359-F do Código Penal, estabelece pena de detenção ou multa, quando a omissão for culposa.","assunção de inscrição de despesas não empenhadas em restos a pagar, previsto no art. 359-B do Código Penal, consuma-se com a simples ordem ou autorização de inscrição em restos a pagar de despesa não empenhada ou que exceda limite estabelecido em lei.","ordenação de despesa não autorizada, previsto no art. 359-D do Código Penal, não admite o dolo eventual, não se caracterizando quando o agente público que ordena a despesa está em dúvida quanto à existência ou não de autorização legal."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 17: Responsabilidade, finanças públicas e LRF.","r":"FCC - ACE II (TCE SE)/TCE SE/Coordenadoria Jurídica/2011 • TEC 2581938","source":"FCC - ACE II (TCE SE)/TCE SE/Coordenadoria Jurídica/2011","subject":"Direito Penal - Dos Crimes contra as Finanças Públicas (arts. 359-A a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2581938","year":2011,"caderno":6,"classificationReason":"Crimes contra as finanças públicas expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3956106","sourceQuestionId":"3956106","t":"pen-m12","moduleId":"pen-m12","q":"Sobre os crimes em espécie, avalie as proposições a seguir: I. O agente que facilita a fuga de jovem de 18 anos submetido à medida socioeducativa de semiliberdade pratica o crime de fuga de pessoa presa. II. Não comete a infração penal de apologia de crime, o agente que se vale de um carro de som e incentiva os moradores de um bairro a agredirem até a morte as pessoas em situação de rua da cidade. III. A reunião de quatro indivíduos para furtar três motocicletas em Teixeira de Freitas, visando a venda e posterior repartição do valor arrecadado, não configura o crime de associação criminosa. IV. O agente que é flagrado, durante a revista pessoal, tentando ingressar no estabelecimento prisional com um chip de telefone celular escondido sob suas vestes não pratica o crime de favorecimento real impróprio na forma consumada, mas na forma tentada. Está correto o que se afirma APENAS em","o":["II e III.","I, II e IV.","II e IV.","I, III e IV.","II, III e IV."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - DP BA/DPE BA/2026 • TEC 3956106","source":"FCC - DP BA/DPE BA/2026","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3956106","year":2026,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-3231595","sourceQuestionId":"3231595","t":"pen-m12","moduleId":"pen-m12","q":"Rinaldo, funcionário público, auditor fiscal de um determinado Estado Brasileiro, comparece na empresa \"X· para realizar a fiscalização tributária, após suspeitas de que a referida empresa estaria suprimindo tributo, prestando declaração falsa às autoridades fazendárias. Quando Rinaldo chegou no estabelecimento para realizar a fiscalização, um dos sócios da empresa \"X\" lhe ofereceu RS 50.000,00 para deixar de elaborar o Auto de Infração e cobrar o tributo suprimido. Rinaldo aceita a promessa de vantagem oferecida e vai embora da empresa certificando que não há qualquer irregularidade. Neste caso, Rinaldo cometeu, em tese, crime","o":["de corrupção passiva, previsto no artigo 317, do Código Penal, com pena prevista de reclusão, de 2 a 12 anos, e multa.","de peculato, previsto no artigo 312, do Código Penal, com pena prevista de reclusão, de 2 a 12 anos, e multa.","de inserção de dados falsos em sistema de informações, previsto no artigo 313-A, do Código Penal, com pena prevista de reclusão, de 2 a 12 anos, e multa.","funcional contra a ordem tributária, previsto na Lei n\" 8.137/90, com pena prevista de reclusão, de 3 a 8 anos, e multa.","de concussão, previsto no artigo 316, do Código Penal, cem pena prevista de reclusão, de 2 a 12 anos, e multa."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Ana Prev (PIAUÍPREV)/PIAUÍPREV/2024 • TEC 3231595","source":"FCC - Ana Prev (PIAUÍPREV)/PIAUÍPREV/2024","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3231595","year":2024,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2348510","sourceQuestionId":"2348510","t":"pen-m12","moduleId":"pen-m12","q":"Arthur mantinha um estabelecimento no centro da cidade onde explorava a prática ilegal de jogos de azar. Tomando ciência desse fato, os policiais civis Bruno e Cândido dirigiram-se até o local, ocasião em que lhes foi oferecida, por parte de Arthur, determinada quantia em dinheiro para que não fossem apreendidos os equipamentos de jogo ilegal, o que foi por eles prontamente aceito. Diante da situação hipotética acima mencionada,","o":["todos os envolvidos praticaram o crime de corrupção ativa.","Arthur praticou o crime de corrupção passiva, enquanto Bruno e Cândido praticaram o crime de corrupção ativa.","Arthur praticou o crime de corrupção ativa, enquanto Bruno e Cândido praticaram o crime de corrupção passiva.","todos os envolvidos praticaram o crime de corrupção passiva.","a conduta de Arthur somente será enquadrada como contravenção pela prática de jogos de azar, enquanto a dos policiais será tipificada como corrupção ativa."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Sold (PM BA)/PM BA/2023 • TEC 2348510","source":"FCC - Sold (PM BA)/PM BA/2023","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2348510","year":2023,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2821151","sourceQuestionId":"2821151","t":"pen-m12","moduleId":"pen-m12","q":"Considere os seguintes tipos penais praticados contra a Administração Pública: Tipos penais Ação a. Solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda 1. Desobediência que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, ou aceitar promessa de tal vantagem. b. Exigir, para si ou para outrem, direta ou indiretamente, ainda que fora da função 2. Resistência ou antes de assumi-la, mas em razão dela, vantagem indevida. c. Opor-se à execução de ato legal, mediante violência ou ameaça a 3. Corrupção passiva funcionário competente para executá-lo ou a quem lhe esteja prestando auxílio. d. Desobedecer a ordem legal de 4. Corrupção ativa funcionário público. e. Oferecer ou prometer vantagem indevida a funcionário público, para 5. Concussão determiná-lo a praticar, omitir ou retardar ato de ofício. A correta correlação entre o tipo penal e a sua ação é:","o":["1d - 2a - 3b - 4e - 5c","1a - 2c - 3d - 4e - 5b","1d - 2c - 3a - 4e - 5b","1d - 2b - 3a - 4e - 5c","1e - 2c - 3a - 4d - 5b"],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TJ TRT12/TRT 12/Administrativa/Agente da Policia Judicial/2023 • TEC 2821151","source":"FCC - TJ TRT12/TRT 12/Administrativa/Agente da Policia Judicial/2023","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2821151","year":2023,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2068112","sourceQuestionId":"2068112","t":"pen-m12","moduleId":"pen-m12","q":"Considere as seguintes situações hipotéticas: I. Romeu, funcionário de um cartório de registro civil, pede vultosa quantia em dinheiro para Edgar, para expedir certidão com teor diferente do que seria o correto. II. Julieta oferece dinheiro a Willian, policial militar, para que não seja formalizado o flagrante de crime de trânsito por ela praticado. Diante do exposto, e com base nas informações acima, em tese, Romeu","o":["praticou o crime de corrupção ativa e Julieta o crime de corrupção passiva.","não praticou qualquer crime, pois sua função não pode ser equiparada a de funcionário público, enquanto Julieta praticou o crime de desobediência.","praticou o crime de corrupção qualificada e Julieta o crime de desacato.","praticou o crime de corrupção passiva enquanto Julieta não praticou qualquer ilícito penal, haja vista que sua conduta é mera infração administrativa.","praticou o crime de corrupção passiva e Julieta o crime de corrupção ativa."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TNS (Pref Teresina)/Pref Teresina/Fiscal de Serviços Públicos/2022 • TEC 2068112","source":"FCC - TNS (Pref Teresina)/Pref Teresina/Fiscal de Serviços Públicos/2022","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2068112","year":2022,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-2068115","sourceQuestionId":"2068115","t":"pen-m12","moduleId":"pen-m12","q":"Considere as seguintes situações hipotéticas: I. Sônia, tesoureira de uma repartição pública, se apropriou de dinheiro de diárias de outros funcionários que ali trabalhavam. II. Murilo, chefe de uma repartição de determinada Prefeitura Municipal, deixou, por indulgência, de responsabilizar Maurício, seu subordinado, ao tomar conhecimento de que ele havia cometido determinada infração no exercício do cargo. Diante do exposto, e com base nas informações acima, em tese, Sônia praticou o crime de","o":["peculato e Murilo o crime de condescendência criminosa.","corrupção ativa e Murilo o crime de prevaricação.","peculato e Murilo o crime de advocacia administrativa.","corrupção passiva e Murilo o crime de prevaricação.","emprego irregular de verbas públicas e Murilo o crime de condescendência criminosa."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TNS (Pref Teresina)/Pref Teresina/Fiscal de Serviços Públicos/2022 • TEC 2068115","source":"FCC - TNS (Pref Teresina)/Pref Teresina/Fiscal de Serviços Públicos/2022","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2068115","year":2022,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-789044","sourceQuestionId":"789044","t":"pen-m12","moduleId":"pen-m12","q":"Relativos aos crimes contra a Administração pública, considere: I. Caracteriza-se o crime de peculato na apropriação ou desvio pelo funcionário público de dinheiro, valor ou qualquer outro bem móvel, desde que público, de que tem a posse em razão do cargo, para proveito próprio. II. Se o funcionário exige tributo ou contribuição social que sabe ou deveria saber indevido ou, quando devido, emprega na cobrança meio vexatório ou gravoso, que a lei não autoriza, configura-se o crime de excesso de exação. III. É crime de prevaricação deixar o Diretor de Penitenciária e/ou agente público, de cumprir seu dever de vedar ao preso o acesso a aparelho eletrônico, de rádio ou similar, que permita a comunicação com outros presos ou com o ambiente externo. IV. Para os efeitos penais dessa espécie de crimes, considera-se funcionário público quem, embora transitoriamente, mas desde que remunerado, exerce cargo, emprego ou função pública. Está correto o que se afirma APENAS em","o":["II e III.","III e IV.","I, II e IV.","I e IV.","I, II e III."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789044","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789044","year":2019,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-1016718","sourceQuestionId":"1016718","t":"pen-m12","moduleId":"pen-m12","q":"Segundo o Código Penal brasileiro, bem como o entendimento dos Tribunais Superiores, sobre os crimes contra a Administração Pública,","o":["no caso de peculato culposo, a reparação do dano, se precede à sentença irrecorrível, reduz de metade a pena imposta.","de acordo com a jurisprudência nacional, o princípio da insignificância é inaplicável aos crimes de peculato.","o funcionário público que solicitar para si, diretamente, em razão da função, vantagem indevida, pratica, em tese, o crime de corrupção ativa.","somente o advogado, inscrito na Ordem dos Advogados do Brasil, poderá ser sujeito ativo do crime de advocacia administrativa.","para a consumação do crime de concussão é necessário que o agente receba a vantagem indevida."],"a":1,"e":"Gabarito do caderno: B. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AFTM (Pref SJRP)/Pref SJRP/2019 • TEC 1016718","source":"FCC - AFTM (Pref SJRP)/Pref SJRP/2019","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1016718","year":2019,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-660044","sourceQuestionId":"660044","t":"pen-m12","moduleId":"pen-m12","q":"Sobre os crimes contra a Administração Pública, comete o crime de","o":["corrupção ativa aquele que exige, para si, direta ou indiretamente, ainda que fora da função, mas em razão dela, vantagem indevida.","prevaricação aquele que, por indulgência, deixa de responsabilizar subordinado que cometeu infração no exercício do cargo.","condescendência criminosa aquele que se opõe à execução de ato legal, mediante violência ou ameaça a funcionário competente para executá-lo.","denunciação caluniosa aquele que provoca a ação de autoridade, comunicando-lhe a ocorrência de crime que sabe não ter ocorrido.","peculato aquele que se apropria de dinheiro, valor ou qualquer outro bem móvel, público ou particular, de que tem a posse em razão do cargo, em proveito próprio ou alheio."],"a":4,"e":"Gabarito do caderno: E. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AFT I (Pref São Luís)/Pref São Luís/Abrangência Geral/2018 • TEC 660044","source":"FCC - AFT I (Pref São Luís)/Pref São Luís/Abrangência Geral/2018","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/660044","year":2018,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-357283","sourceQuestionId":"357283","t":"pen-m12","moduleId":"pen-m12","q":"A respeito dos crimes de corrupção ativa e passiva, considere: I. O delito de corrupção ativa não se caracteriza quando, apesar da solicitação de vantagem indevida, o resultado pretendido pelo agente não ocorreu. II. O crime de corrupção passiva só se configura com a ocorrência simultânea do crime de corrupção ativa. III. É indispensável para a caracterização do delito de corrupção ativa que a solicitação de recebimento de vantagem indevida tenha relação com a função pública exercida pelo agente. Está correto o que consta APENAS em","o":["I e III.","I e II.","II e III.","III.","II."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - TJ TRF3/TRF 3/Apoio Especializado/Informática/2016 • TEC 357283","source":"FCC - TJ TRF3/TRF 3/Apoio Especializado/Informática/2016","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/357283","year":2016,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-358398","sourceQuestionId":"358398","t":"pen-m12","moduleId":"pen-m12","q":"A respeito dos Crimes contra a Administração pública, é INCORRETO afirmar que","o":["o particular pode ser coautor do crime de concussão.","comete o crime de excesso de exação o funcionário que emprega meio vexatório na cobrança de tributo.","o crime de prevaricação exige o intuito do agente de satisfazer interesse ou sentimento pessoal.","comete crime de corrupção passiva quem oferece dinheiro a funcionário público para determiná-lo a retardar ato de ofício.","o ato de desferir um tapa no rosto de funcionário público, em razão da sua função, sem causar lesão, pode caracterizar o crime de desacato."],"a":3,"e":"Gabarito do caderno: D. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRF3/TRF 3/Administrativa/2016 • TEC 358398","source":"FCC - AJ TRF3/TRF 3/Administrativa/2016","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/358398","year":2016,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-358621","sourceQuestionId":"358621","t":"pen-m12","moduleId":"pen-m12","q":"A respeito dos Crimes Contra a Administração pública, considere: I. Comete o crime de condescendência criminosa o funcionário público que, por indulgência, sabendo da prática de infração administrativa por parte de subordinado, deixa, quando lhe faltar competência para responsabilizar o subordinado, de levar o fato ao conhecimento da autoridade competente. II. Equipara-se a funcionário público a pessoa que trabalha para empresa prestadora de serviço contratada ou conveniada para a execução de atividade típica da Administração. III. Não configura desacato a ofensa dirigida a funcionário público em razão de suas funções se não estiver no exercício dessas funções no momento da ofensa. Está correto o que consta APENAS em","o":["I e II.","I e III.","II e III.","III.","II."],"a":0,"e":"Gabarito do caderno: A. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - AJ TRF3/TRF 3/Apoio Especializado/Medicina (Clínica Geral)/2016 • TEC 358621","source":"FCC - AJ TRF3/TRF 3/Apoio Especializado/Medicina (Clínica Geral)/2016","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/358621","year":2016,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-penal-256977","sourceQuestionId":"256977","t":"pen-m12","moduleId":"pen-m12","q":"Paulo, sócio administrador de agência de turismo, ofereceu uma viagem à Europa a Jack, agente fiscal de rendas, para determiná-lo a não autuá-lo por sonegação de tributo estadual. Jack aceitou a oferta, viajou e, quando voltou, foi até a empresa e lavrou auto de infração pela sonegação do referido tributo. Nesse caso,","o":["Paulo responderá por corrupção ativa e Jack por prevaricação.","não há crime, porque o auto de infração foi lavrado, não tendo havido prejuízo para a Administração pública.","Jack responderá por corrupção passiva e Paulo por corrupção ativa.","Paulo responderá por corrupção ativa e Jack não responderá por nenhum delito por ter lavrado o auto de infração.","Jack responderá por corrupção passiva e Paulo por prevaricação."],"a":2,"e":"Gabarito do caderno: C. Tema classificado no Módulo 12: Crimes contra a Administração Pública.","r":"FCC - Proc MPC (TCM-GO)/TCM GO/2015 • TEC 256977","source":"FCC - Proc MPC (TCM-GO)/TCM GO/2015","subject":"Direito Penal - Questões Mescladas sobre Crimes contra a Administração Pública (arts. 312 a 359-H do CP)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/256977","year":2015,"caderno":6,"classificationReason":"Crimes contra a Administração Pública expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"});
